public static int findNthLeapYear(int Y, int N) {
    if (Y <= 0 || N <= 0) {
        throw new IllegalArgumentException("Y and N must be positive integers");
    }

    int year = Y;

    // Find the first leap year that is >= Y
    while (!((year % 4 == 0 && year % 100 != 0) || (year % 400 == 0))) {
        year++;
    }

    int count = 1; // The first leap year found

    if (count == N) {
        return year;
    }

    // Find subsequent leap years until the Nth is reached
    while (count < N) {
        year++;
        while (!((year % 4 == 0 && year % 100 != 0) || (year % 400 == 0))) {
            year++;
        }
        count++;
    }

    return year;
}

public static int calculateTimeNeeded(int N) {
    int half = N / 2;                     // floor(N/2)
    int otherHalf = N - half;             // ceil(N/2)
    return half * (otherHalf - 1);
}

