public List<List<Integer>> permute(int[] nums) {
    java.util.List<java.util.List<Integer>> res = new java.util.ArrayList<>();
    int n = nums.length;
    if (n == 0) return res;
    int[] perm = nums.clone();
    java.util.Arrays.sort(perm);
    while (true) {
        java.util.List<Integer> cur = new java.util.ArrayList<>(n);
        for (int k = 0; k < n; k++) cur.add(perm[k]);
        res.add(cur);
        int i = n - 1;
        while (i > 0 && perm[i - 1] >= perm[i]) i--;
        if (i == 0) break;
        int j = n - 1;
        while (perm[i - 1] >= perm[j]) j--;
        int temp = perm[i - 1];
        perm[i - 1] = perm[j];
        perm[j] = temp;
        int l = i, r = n - 1;
        while (l < r) {
            temp = perm[l];
            perm[l] = perm[r];
            perm[r] = temp;
            l++;
            r--;
        }
    }
    return res;
}

public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }
    // Determine the maximum string length to set upper bound for L
    int maxLen = 0;
    for (String s : strings) {
        if (s == null) continue;
        maxLen = Math.max(maxLen, s.length());
    }
    // Try lengths from maxLen down to 1
    for (int L = maxLen; L >= 1; L--) {
        java.util.Set<String> candidates = null;
        boolean failed = false;
        for (String s : strings) {
            if (s == null || s.length() < L) {
                failed = true;
                break;
            }
            java.util.Set<String> current = new java.util.HashSet<>();
            for (int i = 0; i <= s.length() - L; i++) {
                String sub = s.substring(i, i + L);
                current.add(sub);
                // Add the reversed variant as well
                current.add(new java.lang.StringBuilder(sub).reverse().toString());
            }
            if (candidates == null) {
                candidates = current;
            } else {
                candidates.retainAll(current);
                if (candidates.isEmpty()) {
                    failed = true;
                    break;
                }
            }
        }
        if (!failed && candidates != null && !candidates.isEmpty()) {
            return L;
        }
    }
    return 0; // No common substring found
}

public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }
    Set<String> globalSubstrings = new HashSet<>();
    List<String> substrList = new ArrayList<>();

    for (String s : strings) {
        if (s == null) {
            continue;
        }
        int n = s.length();
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j <= n; j++) {
                String sub = s.substring(i, j);
                globalSubstrings.add(sub);
                substrList.add(sub);
            }
        }
    }

    int maxLen = 0;
    for (String sub : substrList) {
        String rev = new StringBuilder(sub).reverse().toString();
        if (globalSubstrings.contains(rev)) {
            if (sub.length() > maxLen) {
                maxLen = sub.length();
            }
        }
    }

    return maxLen;
}

