public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }
    // Find the shortest string to minimize substring enumeration
    String base = null;
    int minLen = Integer.MAX_VALUE;
    for (String s : strings) {
        if (s == null) {
            return 0;
        }
        if (s.length() < minLen) {
            minLen = s.length();
            base = s;
        }
    }
    if (minLen == 0) {
        return 0;
    }
    // Iterate over possible lengths from longest to shortest
    for (int len = minLen; len >= 1; len--) {
        // Create all substrings of 'base' with current length
        Set<String> candidates = new HashSet<>();
        for (int i = 0; i + len <= base.length(); i++) {
            candidates.add(base.substring(i, i + len));
        }
        // Test each candidate against all strings
        for (String candidate : candidates) {
            String reversed = new StringBuilder(candidate).reverse().toString();
            boolean common = true;
            for (String s : strings) {
                if (!(s.contains(candidate) || s.contains(reversed))) {
                    common = false;
                    break;
                }
            }
            if (common) {
                return len;
            }
        }
    }
    return 0;
}

public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }
    String first = strings.get(0);
    int maxLen = first.length();

    for (int len = maxLen; len >= 1; len--) {
        outer:
        for (int start = 0; start <= first.length() - len; start++) {
            String candidate = first.substring(start, start + len);
            String candidateRev = new StringBuilder(candidate).reverse().toString();

            for (int idx = 1; idx < strings.size(); idx++) {
                String s = strings.get(idx);
                if (!(s.contains(candidate) || s.contains(candidateRev))) {
                    continue outer;
                }
            }
            return len; // Found the longest length
        }
    }
    return 0;
}

