public static int countDoubles(int[] numbers) {
    Map<Integer, Integer> freq = new HashMap<>();
    for (int n : numbers) {
        freq.put(n, freq.getOrDefault(n, 0) + 1);
    }
    int count = 0;
    for (int n : numbers) {
        if (n % 2 != 0) {
            continue;
        }
        int half = n / 2;
        if (freq.containsKey(half)) {
            if (half != n) {
                count++;
            } else {
                // n is 0 or any number where half equals itself
                if (freq.get(half) > 1) {
                    count++;
                }
            }
        }
    }
    return count;
}

