public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    // Build adjacency list from given paths
    java.util.Map<String, java.util.List<String>> graph = new java.util.HashMap<>();
    for (int i = 0; i < paths.length; i++) {
        int[] edge = paths[i];
        if (edge.length < 4) continue; // Invalid edge specification, skip
        String a = edge[0] + "," + edge[1];
        String b = edge[2] + "," + edge[3];
        graph.computeIfAbsent(a, k -> new java.util.ArrayList<>()).add(b);
        graph.computeIfAbsent(b, k -> new java.util.ArrayList<>()).add(a);
    }

    // Convert start and end coordinates to string keys
    String startKey = start[0] + "," + start[1];
    String endKey = end[0] + "," + end[1];

    // If start equals end, it's trivially reachable
    if (startKey.equals(endKey)) return "can be travelled";

    // Breadth‑first search to find a path
    java.util.Queue<String> queue = new java.util.LinkedList<>();
    java.util.Set<String> visited = new java.util.HashSet<>();
    queue.add(startKey);
    visited.add(startKey);

    while (!queue.isEmpty()) {
        String current = queue.poll();
        java.util.List<String> neighbors = graph.get(current);
        if (neighbors == null) continue;
        for (String nb : neighbors) {
            if (nb.equals(endKey)) return "can be travelled";
            if (!visited.contains(nb)) {
                visited.add(nb);
                queue.add(nb);
            }
        }
    }

    return "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (n <= 0 || start == null || end == null || start.length == 0 || end.length == 0) {
        return "cannot be travelled";
    }
    int s = start[0];
    int t = end[0];
    if (s < 0 || s >= n || t < 0 || t >= n) {
        return "cannot be travelled";
    }
    @SuppressWarnings("unchecked")
    java.util.List<Integer>[] adj = new java.util.ArrayList[n];
    for (int i = 0; i < n; i++) {
        adj[i] = new java.util.ArrayList<>();
    }
    for (int[] path : paths) {
        if (path == null || path.length < 2) {
            continue;
        }
        int a = path[0];
        int b = path[1];
        if (a >= 0 && a < n && b >= 0 && b < n) {
            adj[a].add(b);
            adj[b].add(a); // assume undirected
        }
    }
    boolean[] visited = new boolean[n];
    java.util.Queue<Integer> queue = new java.util.LinkedList<>();
    queue.offer(s);
    visited[s] = true;
    while (!queue.isEmpty()) {
        int cur = queue.poll();
        if (cur == t) {
            return "can be travelled";
        }
        for (int nb : adj[cur]) {
            if (!visited[nb]) {
                visited[nb] = true;
                queue.offer(nb);
            }
        }
    }
    return "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (start == null || end == null || start.length != 2 || end.length != 2) {
        return "cannot be travelled";
    }
    String startKey = start[0] + "," + start[1];
    String endKey = end[0] + "," + end[1];
    if (startKey.equals(endKey)) {
        return "can be travelled";
    }
    java.util.Set<String> visited = new java.util.HashSet<>();
    java.util.ArrayDeque<String> queue = new java.util.ArrayDeque<>();
    visited.add(startKey);
    queue.add(startKey);
    while (!queue.isEmpty()) {
        String cur = queue.poll();
        if (cur.equals(endKey)) {
            return "can be travelled";
        }
        int[] curCoords = parse(cur);
        for (int[] p : paths) {
            if (p == null || p.length != 4) {
                continue;
            }
            if (p[0] == curCoords[0] && p[1] == curCoords[1]) {
                String neighbor = p[2] + "," + p[3];
                if (visited.add(neighbor)) {
                    queue.add(neighbor);
                }
            } else if (p[2] == curCoords[0] && p[3] == curCoords[1]) {
                String neighbor = p[0] + "," + p[1];
                if (visited.add(neighbor)) {
                    queue.add(neighbor);
                }
            }
        }
    }
    return "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (n <= 0 || start == null || end == null || paths == null) {
        return "cannot be travelled";
    }
    int startId = start[0] * n + start[1];
    int endId = end[0] * n + end[1];
    if (startId == endId) {
        return "can be travelled";
    }
    java.util.Map<Integer, java.util.List<Integer>> adjacency = new java.util.HashMap<>();
    for (int[] p : paths) {
        if (p.length != 4) continue; // skip invalid entries
        int r1 = p[0], c1 = p[1], r2 = p[2], c2 = p[3];
        if (r1 < 0 || r1 >= n || c1 < 0 || c1 >= n || r2 < 0 || r2 >= n || c2 < 0 || c2 >= n) {
            continue;
        }
        int id1 = r1 * n + c1;
        int id2 = r2 * n + c2;
        adjacency.computeIfAbsent(id1, k -> new java.util.ArrayList<>()).add(id2);
        adjacency.computeIfAbsent(id2, k -> new java.util.ArrayList<>()).add(id1);
    }
    java.util.Queue<Integer> queue = new java.util.LinkedList<>();
    java.util.Set<Integer> visited = new java.util.HashSet<>();
    queue.add(startId);
    visited.add(startId);
    while (!queue.isEmpty()) {
        int cur = queue.poll();
        java.util.List<Integer> neighbors = adjacency.getOrDefault(cur, java.util.Collections.emptyList());
        for (int nb : neighbors) {
            if (nb == endId) {
                return "can be travelled";
            }
            if (!visited.contains(nb)) {
                visited.add(nb);
                queue.add(nb);
            }
        }
    }
    return "cannot be travelled";
}

public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    if (start == null || end == null || start.length == 0 || end.length == 0) {
        return "cannot be travelled";
    }
    int source = start[0];
    int target = end[0];
    // build adjacency list
    List<List<Integer>> adj = new ArrayList<>(n);
    for (int i = 0; i < n; i++) {
        adj.add(new ArrayList<>());
    }
    for (int[] p : paths) {
        if (p == null || p.length < 2) continue;
        int a = p[0];
        int b = p[1];
        if (a >= 0 && a < n && b >= 0 && b < n) {
            adj.get(a).add(b);
            adj.get(b).add(a);
        }
    }
    boolean[] visited = new boolean[n];
    Queue<Integer> queue = new ArrayDeque<>();
    queue.offer(source);
    visited[source] = true;
    while (!queue.isEmpty()) {
        int cur = queue.poll();
        if (cur == target) {
            return "can be travelled";
        }
        for (int neighbor : adj.get(cur)) {
            if (!visited[neighbor]) {
                visited[neighbor] = true;
                queue.offer(neighbor);
            }
        }
    }
    return "cannot be travelled";
}

public static String appx(String word1, String word2) {
    int len1 = word1.length();
    int len2 = word2.length();
    int denominator = len1 + len2;

    // Build sets of unique characters for each word
    java.util.Set<Character> set1 = new java.util.HashSet<>();
    java.util.Set<Character> set2 = new java.util.HashSet<>();
    for (char c : word1.toCharArray()) {
        set1.add(c);
    }
    for (char c : word2.toCharArray()) {
        set2.add(c);
    }

    // Count distinct common letters
    int commonCount = 0;
    for (char c : set1) {
        if (set2.contains(c)) {
            commonCount++;
        }
    }

    int numerator = 2 * commonCount; // each common letter counted in both words

    if (numerator == 0) {
        return "appx(" + word1 + ", " + word2 + ") = 0";
    }

    // Reduce fraction to lowest terms
    int gcd = java.lang.Math.abs(gcd(numerator, denominator));
    int redNum = numerator / gcd;
    int redDen = denominator / gcd;

    String value;
    if (redDen == 1) {
        value = Integer.toString(redNum);
    } else {
        value = redNum + "/" + redDen;
    }

    return "appx(" + word1 + ", " + word2 + ") = " + value;
}

