public boolean canArrange(int[] arr, int k) {
    if (arr == null || arr.length % 2 != 0) {
        return false;
    }
    int[] freq = new int[k];
    for (int num : arr) {
        int r = num % k;
        if (r < 0) {
            r += k;
        }
        freq[r]++;
    }
    // Check remainder 0
    if (freq[0] % 2 != 0) {
        return false;
    }
    // Check pairs of remainders
    for (int r = 1; r <= k / 2; r++) {
        if (r == k - r) { // when k is even and r == k/2
            if (freq[r] % 2 != 0) {
                return false;
            }
        } else {
            if (freq[r] != freq[k - r]) {
                return false;
            }
        }
    }
    return true;
}

public boolean canArrange(int[] arr, int k) {
    if (arr == null || arr.length % 2 != 0) {
        return false;
    }
    int[] freq = new int[k];
    for (int num : arr) {
        int rem = ((num % k) + k) % k;
        freq[rem]++;
    }
    // Check remainder 0
    if (freq[0] % 2 != 0) {
        return false;
    }
    // If k is even, check remainder k/2
    if (k % 2 == 0 && freq[k / 2] % 2 != 0) {
        return false;
    }
    // Check other remainders
    for (int r = 1; r < k; r++) {
        if (r == k - r) {
            continue; // already handled
        }
        if (freq[r] != freq[k - r]) {
            return false;
        }
    }
    return true;
}

public boolean canArrange(int[] arr, int k) {
    if (arr == null || arr.length % 2 != 0) {
        return false;
    }
    int[] count = new int[k];
    for (int num : arr) {
        int r = Math.floorMod(num, k);
        count[r]++;
    }
    if (count[0] % 2 != 0) {
        return false;
    }
    if (k % 2 == 0) {
        if (count[k / 2] % 2 != 0) {
            return false;
        }
    }
    for (int r = 1; r < k; r++) {
        int opp = k - r;
        if (r > opp) {
            continue;
        }
        if (count[r] != count[opp]) {
            return false;
        }
    }
    return true;
}

public boolean canArrange(int[] arr, int k) {
    if (arr == null) return false;
    int n = arr.length;
    if (n % 2 != 0) return false;
    if (k <= 0) return false;
    int[] freq = new int[k];
    for (int num : arr) {
        int r = ((num % k) + k) % k;
        freq[r]++;
    }
    if (freq[0] % 2 != 0) return false;
    if (k % 2 == 0 && freq[k / 2] % 2 != 0) return false;
    for (int r = 1; r <= k / 2; r++) {
        if (r == k - r) continue;
        if (freq[r] != freq[k - r]) return false;
    }
    return true;
}

public boolean canArrange(int[] arr, int k) {
    if (arr.length % 2 != 0) return false; // odd length cannot form pairs
    if (k == 0) return false; // division by zero not allowed

    int[] freq = new int[k];
    for (int num : arr) {
        int r = num % k;
        if (r < 0) r += k; // handle negative numbers
        freq[r]++;
    }

    // Remainder 0 pairs
    if (freq[0] % 2 != 0) return false;

    // If k is even, remainder k/2 must also pair up
    if (k % 2 == 0) {
        if (freq[k / 2] % 2 != 0) return false;
    }

    // Check pairs of complementary remainders
    for (int r = 1; r < (k + 1) / 2; r++) {
        if (freq[r] != freq[k - r]) {
            return false;
        }
    }

    return true;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    java.util.List<Integer>[] graph = new java.util.ArrayList[n];
    for (int i = 0; i < n; i++) {
        graph[i] = new java.util.ArrayList<>();
    }
    for (int[] e : edges) {
        graph[e[0]].add(e[1]);
        graph[e[1]].add(e[0]);
    }
    int[] res = new int[1];
    class Helper {
        boolean dfs(int node, int parent) {
            boolean containsApple = hasApple[node];
            for (int nei : graph[node]) {
                if (nei == parent) continue;
                if (dfs(nei, node)) {
                    res[0] += 2;
                    containsApple = true;
                }
            }
            return containsApple;
        }
    }
    new Helper().dfs(0, -1);
    return res[0];
}

