}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // Build adjacency list
    ArrayList<Integer>[] graph = new ArrayList[n];
    for (int i = 0; i < n; i++) {
        graph[i] = new ArrayList<>();
    }
    for (int[] e : edges) {
        int a = e[0];
        int b = e[1];
        graph[a].add(b);
        graph[b].add(a);
    }

    int[] parent = new int[n];
    int[] order = new int[n];
    int orderSize = 0;

    // Iterative DFS to establish parent order
    int[] stack = new int[n];
    int sp = 0;
    stack[sp++] = 0;
    parent[0] = -2; // root has no parent
    while (sp > 0) {
        int node = stack[--sp];
        order[orderSize++] = node;
        for (int nb : graph[node]) {
            if (nb != parent[node]) {
                parent[nb] = node;
                stack[sp++] = nb;
            }
        }
    }

    boolean[] subtreeHasApple = new boolean[n];
    int totalTime = 0;

    // Process nodes in reverse order (post-order)
    for (int i = orderSize - 1; i >= 0; i--) {
        int node = order[i];
        boolean has = hasApple[node];
        for (int nb : graph[node]) {
            if (nb != parent[node]) {
                has = has || subtreeHasApple[nb];
            }
        }
        subtreeHasApple[node] = has;
        if (node != 0 && has) {
            totalTime += 2; // go to node and return
        }
    }

    return totalTime;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    java.util.List<Integer>[] adj = new java.util.ArrayList[n];
    for (int i = 0; i < n; i++) {
        adj[i] = new java.util.ArrayList<>();
    }
    for (int[] e : edges) {
        adj[e[0]].add(e[1]);
        adj[e[1]].add(e[0]);
    }
    class DFS {
        int dfs(int node, int parent) {
            int total = 0;
            for (int child : adj[node]) {
                if (child == parent) continue;
                int childTime = dfs(child, node);
                if (childTime > 0 || hasApple[child]) {
                    total += childTime + 2;
                }
            }
            return total;
        }
    }
    return new DFS().dfs(0, -1);
}

public String sortString(String s) {
    TreeMap<Character, Integer> freq = new TreeMap<>();
    for (char c : s.toCharArray()) {
        freq.put(c, freq.getOrDefault(c, 0) + 1);
    }
    StringBuilder result = new StringBuilder();
    while (!freq.isEmpty()) {
        // Ascending pass
        for (Character c : new ArrayList<>(freq.keySet())) {
            result.append(c);
            int count = freq.get(c) - 1;
            if (count == 0) {
                freq.remove(c);
            } else {
                freq.put(c, count);
            }
        }
        if (freq.isEmpty()) break;
        // Descending pass
        for (Character c : new ArrayList<>(freq.descendingKeySet())) {
            result.append(c);
            int count = freq.get(c) - 1;
            if (count == 0) {
                freq.remove(c);
            } else {
                freq.put(c, count);
            }
        }
    }
    return result.toString();
}

public String sortString(String s) {
    int n = s.length();
    if (n == 0) return "";
    int[] freq = new int[256];
    for (int i = 0; i < n; i++) {
        freq[s.charAt(i)]++;
    }
    StringBuilder sb = new StringBuilder();
    int remaining = n;
    while (remaining > 0) {
        // Ascending part
        for (int i = 0; i < 256; i++) {
            if (freq[i] == 0) continue;
            sb.append((char) i);
            freq[i]--;
            remaining--;
            int last = i;
            for (int j = last + 1; j < 256; j++) {
                if (freq[j] == 0) continue;
                sb.append((char) j);
                freq[j]--;
                remaining--;
                last = j;
            }
            break;
        }
        if (remaining == 0) break;
        // Descending part
        for (int i = 255; i >= 0; i--) {
            if (freq[i] == 0) continue;
            sb.append((char) i);
            freq[i]--;
            remaining--;
            int last = i;
            for (int j = last - 1; j >= 0; j--) {
                if (freq[j] == 0) continue;
                sb.append((char) j);
                freq[j]--;
                remaining--;
                last = j;
            }
            break;
        }
    }
    return sb.toString();
}

public String sortString(String s) {
    if (s == null || s.isEmpty()) {
        return "";
    }
    int[] freq = new int[26];
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c >= 'a' && c <= 'z') {
            freq[c - 'a']++;
        }
    }
    StringBuilder sb = new StringBuilder();
    int remaining = s.length();
    while (remaining > 0) {
        // Ascending pass
        int i = 0;
        while (i < 26 && freq[i] == 0) i++;
        if (i >= 26) break;
        sb.append((char) (i + 'a'));
        freq[i]--;
        remaining--;
        int last = i;
        for (i = last + 1; i < 26; i++) {
            if (freq[i] > 0) {
                sb.append((char) (i + 'a'));
                freq[i]--;
                remaining--;
                last = i;
            }
        }
        if (remaining == 0) break;
        // Descending pass
        int j = 25;
        while (j >= 0 && freq[j] == 0) j--;
        if (j < 0) break;
        sb.append((char) (j + 'a'));
        freq[j]--;
        remaining--;
        int lastDesc = j;
        for (j = lastDesc - 1; j >= 0; j--) {
            if (freq[j] > 0) {
                sb.append((char) (j + 'a'));
                freq[j]--;
                remaining--;
                lastDesc = j;
            }
        }
    }
    return sb.toString();
}

