}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n <= 1) return false;
    int totalSum = 0;
    for (int num : nums) totalSum += num;

    int l1Size = n / 2;
    int l2Size = n - l1Size;

    @SuppressWarnings("unchecked")
    java.util.HashSet<Integer>[] first = new java.util.HashSet[n + 1];
    @SuppressWarnings("unchecked")
    java.util.HashSet<Integer>[] second = new java.util.HashSet[n + 1];
    for (int i = 0; i <= n; i++) {
        first[i] = new java.util.HashSet<>();
        second[i] = new java.util.HashSet<>();
    }

    // Enumerate subsets of the first half
    int limit1 = 1 << l1Size;
    for (int mask = 0; mask < limit1; mask++) {
        int sum = 0;
        int cnt = 0;
        for (int i = 0; i < l1Size; i++) {
            if ((mask & (1 << i)) != 0) {
                sum += nums[i];
                cnt++;
            }
        }
        first[cnt].add(sum);
    }

    // Enumerate subsets of the second half
    int limit2 = 1 << l2Size;
    int offset = l1Size;
    for (int mask = 0; mask < limit2; mask++) {
        int sum = 0;
        int cnt = 0;
        for (int i = 0; i < l2Size; i++) {
            if ((mask & (1 << i)) != 0) {
                sum += nums[offset + i];
                cnt++;
            }
        }
        second[cnt].add(sum);
    }

    // Check possible subset sizes
    for (int k = 1; k < n; k++) {
        if ((totalSum * k) % n != 0) continue;
        int target = (totalSum * k) / n;
        int minFirst = Math.max(0, k - l2Size);
        int maxFirst = Math.min(k, l1Size);
        for (int i = minFirst; i <= maxFirst; i++) {
            int j = k - i;
            if (j < 0 || j > l2Size) continue;
            for (int sumFirst : first[i]) {
                if (second[j].contains(target - sumFirst)) {
                    return true;
                }
            }
        }
    }
    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n < 2) return false;
    int totalSum = 0;
    for (int v : nums) totalSum += v;

    int n1 = n / 2;
    int n2 = n - n1;

    @SuppressWarnings("unchecked")
    HashSet<Integer>[] leftSums = new HashSet[n1 + 1];
    @SuppressWarnings("unchecked")
    HashSet<Integer>[] rightSums = new HashSet[n2 + 1];
    for (int i = 0; i <= n1; i++) leftSums[i] = new HashSet<>();
    for (int i = 0; i <= n2; i++) rightSums[i] = new HashSet<>();

    // generate sums for left half
    int maxMask1 = 1 << n1;
    for (int mask = 0; mask < maxMask1; mask++) {
        int sum = 0;
        int cnt = 0;
        for (int i = 0; i < n1; i++) {
            if ((mask & (1 << i)) != 0) {
                sum += nums[i];
                cnt++;
            }
        }
        leftSums[cnt].add(sum);
    }

    // generate sums for right half
    int maxMask2 = 1 << n2;
    for (int mask = 0; mask < maxMask2; mask++) {
        int sum = 0;
        int cnt = 0;
        for (int i = 0; i < n2; i++) {
            if ((mask & (1 << i)) != 0) {
                sum += nums[n1 + i];
                cnt++;
            }
        }
        rightSums[cnt].add(sum);
    }

    // try all subset sizes
    for (int k = 1; k <= n / 2; k++) {
        if ((totalSum * k) % n != 0) continue;
        int target = (totalSum * k) / n;
        for (int x = 0; x <= k; x++) {
            if (x > n1 || (k - x) > n2) continue;
            for (int leftSum : leftSums[x]) {
                int need = target - leftSum;
                if (rightSums[k - x].contains(need)) {
                    return true;
                }
            }
        }
    }
    return false;
}

public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n <= 1) return false;
    int totalSum = 0;
    for (int num : nums) totalSum += num;
    @SuppressWarnings("unchecked")
    java.util.HashSet<Integer>[] subsets = new java.util.HashSet[n + 1];
    for (int i = 0; i <= n; i++) subsets[i] = new java.util.HashSet<>();
    subsets[0].add(0);
    for (int num : nums) {
        for (int k = n - 1; k >= 0; k--) {
            if (!subsets[k].isEmpty()) {
                for (int sum : subsets[k]) {
                    subsets[k + 1].add(sum + num);
                }
            }
        }
    }
    for (int k = 1; k <= n - 1; k++) {
        if ((long)totalSum * k % n != 0) continue;
        int targetSum = (int)((long)totalSum * k / n);
        if (subsets[k].contains(targetSum)) return true;
    }
    return false;
}

