public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n <= 1) return false;
    long totalSum = 0;
    for (int val : nums) {
        totalSum += val;
    }
    int n1 = n / 2;
    int n2 = n - n1;

    @SuppressWarnings("unchecked")
    ArrayList<Long>[] leftSums = new ArrayList[n1 + 1];
    @SuppressWarnings("unchecked")
    ArrayList<Long>[] rightSums = new ArrayList[n2 + 1];
    for (int i = 0; i <= n1; i++) leftSums[i] = new ArrayList<>();
    for (int i = 0; i <= n2; i++) rightSums[i] = new ArrayList<>();

    // Generate subset sums for left half
    int leftMaskLimit = 1 << n1;
    for (int mask = 0; mask < leftMaskLimit; mask++) {
        long sum = 0;
        int size = 0;
        for (int i = 0; i < n1; i++) {
            if ((mask & (1 << i)) != 0) {
                sum += nums[i];
                size++;
            }
        }
        leftSums[size].add(sum);
    }

    // Generate subset sums for right half
    int rightMaskLimit = 1 << n2;
    for (int mask = 0; mask < rightMaskLimit; mask++) {
        long sum = 0;
        int size = 0;
        for (int i = 0; i < n2; i++) {
            if ((mask & (1 << i)) != 0) {
                sum += nums[n1 + i];
                size++;
            }
        }
        rightSums[size].add(sum);
    }

    // Convert right sums to sets for O(1) lookups
    @SuppressWarnings("unchecked")
    HashSet<Long>[] rightSets = new HashSet[n2 + 1];
    for (int i = 0; i <= n2; i++) {
        rightSets[i] = new HashSet<>(rightSums[i]);
    }

    // Check each possible size k
    for (int k = 1; k < n; k++) {
        if ((totalSum * k) % n != 0) continue; // target sum would not be integer
        long target = (totalSum * k) / n;
        // Try all splits of k into left size a and right size b
        for (int a = 0; a <= n1; a++) {
            int b = k - a;
            if (b < 0 || b > n2) continue;
            for (long sumLeft : leftSums[a]) {
                long requiredRight = target - sumLeft;
                if (rightSets[b].contains(requiredRight)) {
                    return true;
                }
            }
        }
    }
    return false;
}

public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length == 0) {
        return 0;
    }
    int n = cost.length;
    int prevPrev = 0; // minimum cost to reach step 0
    int prev = 0;     // minimum cost to reach step 1
    for (int i = 2; i <= n; i++) {
        int cur = Math.min(prev + cost[i - 1], prevPrev + cost[i - 2]);
        prevPrev = prev;
        prev = cur;
    }
    return prev; // minimum cost to reach the top (step n)
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    if (n == 0) return 0;
    if (n == 1) return cost[0];
    int[] dp = new int[n + 1];
    dp[n] = 0;
    dp[n - 1] = cost[n - 1];
    for (int i = n - 2; i >= 0; i--) {
        dp[i] = cost[i] + Math.min(dp[i + 1], dp[i + 2]);
    }
    return Math.min(dp[0], dp[1]);
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    if (n == 0) {
        return 0;
    }
    if (n == 1) {
        return cost[0];
    }
    int prev = cost[0];
    int curr = cost[1];
    for (int i = 2; i < n; i++) {
        int next = Math.min(curr, prev) + cost[i];
        prev = curr;
        curr = next;
    }
    return Math.min(prev, curr);
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    if (n == 0) return 0;
    // dp[i] represents the minimum cost to reach step i
    int[] dp = new int[n + 1];
    dp[0] = 0;
    dp[1] = 0;  // Starting at step 0 or step 1 costs 0 initially
    for (int i = 2; i <= n; i++) {
        dp[i] = Math.min(dp[i - 1] + cost[i - 1], dp[i - 2] + cost[i - 2]);
    }
    return dp[n];
}

public int minCostClimbingStairs(int[] cost) {
    int n = cost.length;
    int prev2 = 0; // dp[i-2]
    int prev1 = 0; // dp[i-1]
    for (int i = 2; i <= n; i++) {
        int current = Math.min(prev1 + cost[i - 1], prev2 + cost[i - 2]);
        prev2 = prev1;
        prev1 = current;
    }
    return prev1;
}

