public boolean hasAllCodes(String s, int k) {
    int n = s.length();
    if (k > n) return false;
    int total = 1 << k;
    boolean[] seen = new boolean[total];
    int mask = total - 1;
    int curr = 0;
    // Initialize first window
    for (int i = 0; i < k; i++) {
        curr = (curr << 1) | (s.charAt(i) - '0');
    }
    seen[curr] = true;
    int count = 1;
    for (int i = k; i < n; i++) {
        curr = ((curr << 1) & mask) | (s.charAt(i) - '0');
        if (!seen[curr]) {
            seen[curr] = true;
            count++;
            if (count == total) return true; // all codes found early
        }
    }
    return count == total;
}

public boolean hasAllCodes(String s, int k) {
    if (k == 0) {
        return true; // All zero-length strings are present
    }
    if (s == null || s.length() < k) {
        return false;
    }
    int total = 1 << k;
    boolean[] seen = new boolean[total];
    int mask = total - 1;
    int val = 0;
    int count = 0;
    for (int i = 0; i < s.length(); i++) {
        val = ((val << 1) & mask) + (s.charAt(i) == '1' ? 1 : 0);
        if (i >= k - 1) {
            if (!seen[val]) {
                seen[val] = true;
                count++;
                if (count == total) {
                    return true;
                }
            }
        }
    }
    return false;
}

public boolean hasAllCodes(String s, int k) {
    if (k <= 0) return true;
