    boolean[] seen = new boolean[needed];
    int mask = needed - 1;
    int bits = 0;
    int count = 0;
    for (int i = 0; i < s.length(); i++) {
        bits = ((bits << 1) & mask) | (s.charAt(i) - '0');
        if (i >= k - 1) {
            if (!seen[bits]) {
                seen[bits] = true;
                if (++count == needed) return true;
            }
        }
    }
    return count == needed;
}

