public int minInsertions(String s) {
    int insertions = 0;
    int balance = 0;
    for (char c : s.toCharArray()) {
        if (c == '(') {
            balance++;
        } else { // c == ')'
            if (balance == 0) {
                insertions++;   // need a '(' before this ')'
                balance++;       // account for the inserted '('
            }
            balance--;           // consume the ')'
        }
    }
    insertions += balance;      // add ')' for remaining unmatched '('
    return insertions;
}

public int minInsertions(String s) {
    int balance = 0;   // number of unmatched '('
    int insertions = 0; // number of inserted brackets

    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') {
            balance++;
        } else { // c == ')'
            if (balance > 0) {
                balance--; // match a '('
            } else {
                insertions++; // need an '(' inserted before this ')'
                // balance stays 0
            }
        }
    }

    // Any remaining '(' need a ')' inserted after the string
    return insertions + balance;
}

public int minInsertions(String s) {
