    int balance = 0;
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') {
            balance++;
        } else { // c == ')'
            balance--;
            if (balance < 0) {
                insertions++;
                balance = 0;
            }
        }
    }
    return insertions + balance;
