public int minInsertions(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }
    int need = 0;     // insertions needed for unmatched ')'
    int balance = 0;  // current count of unmatched '('
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') {
            balance++;
        } else if (c == ')') {
            balance--;
            if (balance < 0) {
                need++;      // insert '(' before this ')'
                balance = 0;
            }
        }
    }
    // Need 'balance' ')' insertions for remaining '('
    return need + balance;
}

public int minInsertions(String s) {
    int insertions = 0;
    int balance = 0;
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == '(') {
            balance++;
        } else { // c == ')'
            if (balance == 0) {
                // Need an opening bracket before this
                insertions++;
            } else {
                balance--;
            }
        }
    }
    // Any remaining unmatched '(' need closing brackets
    return insertions + balance;
}

public int minOperations(int n) {
    int ops = 0;
    for (int i = 0; i < n; i++) {
        int value = 2 * i + 1;
        int diff = value - n;
        if (diff > 0) {
            ops += diff;
        }
    }
    return ops;
}

public int minOperations(int n) {
    int half = n / 2;          // floor(n/2)
    int higherCount = n - half; // number of elements > n
    return half * higherCount;  // total surplus equals minimal operations
}

public int minOperations(int n) {
    if (n % 2 == 0) {
        int m = n / 2;
        return m * m;
    } else {
        int m = (n - 1) / 2;
        return m * (m + 1);
    }
}

public int minOperations(int n) {
    long total = (long) n * n;
    if (n % 2 == 0) {
        return (int) (total / 4);
    } else {
        return (int) ((total - 1) / 4);
    }
}

public int minOperations(int n) {
    int m = (n - 1) / 2;          // last index where arr[i] <= n
    long result = (long)(m + 1) * (n - 1 - m); // avoid overflow for large n
    return (int)result;
}

