public int findMinFibonacciNumbers(int k) {
    // Generate Fibonacci numbers up to k.
    int[] fib = new int[50]; // enough for k up to 10^9
    fib[0] = 1;
    fib[1] = 1;
    int size = 2;
    while (true) {
        int next = fib[size - 1] + fib[size - 2];
        if (next > k) {
            break;
        }
        fib[size++] = next;
    }

    // Greedy selection of the largest Fibonacci number <= remaining k.
    int count = 0;
    while (k > 0) {
        for (int i = size - 1; i >= 0; i--) {
            if (fib[i] <= k) {
                k -= fib[i];
                count++;
                break;
            }
        }
    }
    return count;
}

public int findMinFibonacciNumbers(int k) {
    // Generate all Fibonacci numbers less than or equal to k
    int[] fib = new int[45]; // The 45th Fibonacci number > int max, but k ≤ 10^9 in LeetCode
    fib[0] = 1;
    fib[1] = 1;
    int size = 2;
    while (fib[size - 1] + fib[size - 2] <= k) {
        fib[size] = fib[size - 1] + fib[size - 2];
        size++;
    }

    int count = 0;
    int remaining = k;
    // Greedy: pick the largest Fibonacci number <= remaining each time
    while (remaining > 0) {
        // Find the largest Fibonacci number not exceeding remaining
        int idx = size - 1;
        while (fib[idx] > remaining) {
            idx--;
        }
        remaining -= fib[idx];
        count++;
    }
    return count;
}

public int findMinFibonacciNumbers(int k) {
    java.util.List<Integer> fibs = new java.util.ArrayList<>();
    fibs.add(1);
