    while (true) {
        int n = fibs.size();
        long next = (long) fibs.get(n - 1) + fibs.get(n - 2);
        if (next > k) break;
        fibs.add((int) next);
    }
    int count = 0;
    int remaining = k;
    for (int i = fibs.size() - 1; i >= 0 && remaining > 0; i--) {
        int f = fibs.get(i);
        if (f <= remaining) {
            remaining -= f;
            count++;
        }
    }
    return count;
}

