public int findMinFibonacciNumbers(int k) {
    List<Integer> fibs = new ArrayList<>();
    int f1 = 1, f2 = 1;
    fibs.add(f1);
    while (f2 <= k) {
        fibs.add(f2);
        int next = f1 + f2;
        f1 = f2;
        f2 = next;
    }

    int count = 0;
    int remaining = k;

    while (remaining > 0) {
        int left = 0, right = fibs.size() - 1;
        while (left < right) {
            int mid = (left + right + 1) / 2;
            if (fibs.get(mid) <= remaining) {
                left = mid;
            } else {
                right = mid - 1;
            }
        }
        int fib = fibs.get(left);
        remaining -= fib;
        count++;
    }

    return count;
}

public int kthFactor(int n, int k) {
    int count = 0;
    for (int i = 1; i <= n; i++) {
        if (n % i == 0) {
            count++;
            if (count == k) {
                return i;
            }
        }
    }
    return -1;
}

public int kthFactor(int n, int k) {
    java.util.ArrayList<Integer> factors = new java.util.ArrayList<>();
    for (long i = 1; i * i <= n; i++) {
        if (n % i == 0) {
            factors.add((int) i);
            if (i != n / i) {
                factors.add((int) (n / i));
            }
        }
    }
    java.util.Collections.sort(factors);
    return k <= factors.size() ? factors.get(k - 1) : -1;
}

public int kthFactor(int n, int k) {
    java.util.ArrayList<Integer> factors = new java.util.ArrayList<>();
    int sqrt = (int) Math.sqrt(n);
    for (int i = 1; i <= sqrt; i++) {
        if (n % i == 0) {
            factors.add(i);
            int other = n / i;
            if (other != i) {
                factors.add(other);
            }
        }
    }
    java.util.Collections.sort(factors);
    if (k > factors.size()) {
        return -1;
    }
    return factors.get(k - 1);
}

public int kthFactor(int n, int k) {
    List<Integer> small = new ArrayList<>();
    List<Integer> large = new ArrayList<>();
    for (int i = 1; i * i <= n; i++) {
        if (n % i == 0) {
            small.add(i);
            int other = n / i;
            if (other != i) {
                large.add(other);
            }
        }
    }
    int total = small.size() + large.size();
    if (k > total) return -1;
    if (k <= small.size()) {
        return small.get(k - 1);
    }
    int largeIndex = k - small.size() - 1;
    return large.get(large.size() - 1 - largeIndex);
}

public int kthFactor(int n, int k) {
    // List to store factors on each side of the square root
    java.util.ArrayList<Integer> small = new java.util.ArrayList<>();
    java.util.ArrayList<Integer> big = new java.util.ArrayList<>();

    int sqrt = (int) Math.sqrt(n);
    for (int i = 1; i <= sqrt; i++) {
        if (n % i == 0) {
            small.add(i);
            int other = n / i;
            if (other != i) {
                big.add(other);
            }
        }
    }

    int totalFactors = small.size() + big.size();
    if (k > totalFactors) {
        return -1;
    }

    if (k <= small.size()) {
        return small.get(k - 1);
    } else {
        // big contains factors greater than sqrt, in the order they were added (ascending from sqrt upwards)
        // To get ascending order we need to access from the end of 'big' list
        int indexInBig = big.size() - (k - small.size());
        return big.get(indexInBig);
    }
}

public String makeGood(String s) {
    StringBuilder stack = new StringBuilder();
    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        int len = stack.length();
        if (len > 0) {
            char last = stack.charAt(len - 1);
            if (Math.abs(last - c) == 32) {
                stack.deleteCharAt(len - 1);
                continue;
            }
        }
        stack.append(c);
    }
    return stack.toString();
}

