public int maxUniqueSplit(String s) {
    int n = s.length();
    int max = 0;
    int totalMasks = 1 << Math.max(0, n - 1);
    for (int mask = 0; mask < totalMasks; mask++) {
        java.util.Set<String> seen = new java.util.HashSet<>();
        int last = 0;
        int count = 0;
        boolean bad = false;
        for (int i = 0; i < n - 1; i++) {
            if ((mask & (1 << i)) != 0) { // split after position i
                String part = s.substring(last, i + 1);
                if (!seen.add(part)) { bad = true; break; }
                count++;
                last = i + 1;
            }
        }
        if (bad) continue;
        String part = s.substring(last);
        if (!seen.add(part)) continue;
        count++;
        if (count > max) max = count;
    }
    return max;
}

public int maxUniqueSplit(String s) {
    if (s == null || s.length() == 0) return 0;
    class Solver {
        int dfs(int pos, java.util.Set<String> used) {
            if (pos == s.length()) return 0;
            int max = 0;
            StringBuilder cur = new StringBuilder();
            for (int i = pos; i < s.length(); i++) {
                cur.append(s.charAt(i));
                String sub = cur.toString();
                if (!used.contains(sub)) {
                    used.add(sub);
                    int val = 1 + dfs(i + 1, used);
                    if (val > max) max = val;
                    used.remove(sub);
                }
            }
            return max;
        }
    }
    return new Solver().dfs(0, new java.util.HashSet<>());
}

public int maxUniqueSplit(String s) {
    int[] max = new int[1];
    java.util.Set<String> used = new java.util.HashSet<>();
    dfs(s, 0, used, max);
    return max[0];
}

