public String getSmallestString(int n, int k) {
    int remaining = k - n; // extra value needed beyond all 'a'
    char[] chars = new char[n];
    // initialize with 'a'
    for (int i = 0; i < n; i++) {
        chars[i] = 'a';
    }
    // fill from the end to keep lexicographically smallest
    for (int i = n - 1; i >= 0 && remaining > 0; i--) {
        int add = Math.min(remaining, 25); // 'z' - 'a' = 25
        chars[i] = (char) ('a' + add);
        remaining -= add;
    }
    return new String(chars);
}

public String getSmallestString(int n, int k) {
    char[] chars = new char[n];
    for (int i = 0; i < n; i++) {
        chars[i] = 'a';
    }
    int surplus = k - n; // amount we need to add beyond all 'a'
    for (int i = n - 1; i >= 0 && surplus > 0; i--) {
        int increment = Math.min(surplus, 25); // max we can add to an 'a' is 25 to reach 'z'
        chars[i] = (char) ('a' + increment);
        surplus -= increment;
    }
    return new String(chars);
}

