public String getSmallestString(int n, int k) {
    char[] res = new char[n];
    int remaining = k;
    for (int i = n - 1; i >= 0; i--) {
        int val = Math.max(1, remaining - 25 * i);
        if (val > 26) val = 26;
        res[i] = (char) ('a' + val - 1);
        remaining -= val;
    }
    return new String(res);
}

