public static int countDigitOne(int n) {
    int count = 0;
    for (long factor = 1; factor <= n; factor *= 10) {
        long lower = n % factor;                     // digits on the right
        int cur = (int) ((n / factor) % 10);          // current digit
        long higher = n / (factor * 10);              // digits on the left

        count += (int) (higher * factor);

        if (cur == 1) {
            count += (int) (lower + 1);
        } else if (cur > 1) {
            count += (int) factor;
        }
    }
    return count;
}

public static int countDigitOne(int n) {
    long count = 0;
    long factor = 1;
    while (factor <= n) {
        long lower   = n % factor;
        int  curr    = (int)((n / factor) % 10);
        long higher  = n / (factor * 10);
        if (curr == 1) {
            count += higher * factor + (lower + 1);
        } else if (curr > 1) {
            count += higher * factor + factor;
        } else { // curr == 0
            count += higher * factor;
        }
        factor *= 10;
    }
    return (int)count;
}

