public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n == 0) return 0;
    boolean[][] ok = new boolean[n][n];
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (i != j) {
                int sum = A[i] + A[j];
                int r = (int) Math.sqrt(sum);
                ok[i][j] = (r * r == sum);
            } else {
                ok[i][j] = false;
            }
        }
    }
    int maxMask = 1 << n;
    int[][] memo = new int[maxMask][n];
    for (int i = 0; i < maxMask; i++) {
        for (int j = 0; j < n; j++) {
            memo[i][j] = -1;
        }
    }
    long total = 0;
    for (int start = 0; start < n; start++) {
        total += dfs(1 << start, start, memo, ok);
    }
    return (int) total;
}

public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n == 0) return 0;
    // Precompute perfect squares up to maximum possible sum
    int maxVal = 0;
    for (int v : A) if (v > maxVal) maxVal = v;
    int maxSum = maxVal * 2;
    boolean[] isSquare = new boolean[maxSum + 1];
    for (int i = 0; i * i <= maxSum; i++) {
        isSquare[i * i] = true;
    }

    Arrays.sort(A);                     // Sort to handle duplicates
    boolean[] used = new boolean[n];
    final int[] count = new int[1];

    // Backtracking function
    java.util.function.IntConsumer backtrack = new java.util.function.IntConsumer() {
        @Override
        public void accept(int prev) {
            if (prev == n) {
                count[0]++;
                return;
            }
            for (int i = 0; i < n; i++) {
                if (used[i]) continue;
                // Skip duplicates: if current number same as previous and previous not used, skip
                if (i > 0 && A[i] == A[i - 1] && !used[i - 1]) continue;
                if (prev == 0 || isSquare[A[prev - 1] + A[i]]) {
                    used[i] = true;
                    backtrack.accept(prev + 1);
                    used[i] = false;
                }
            }
        }
    };

    backtrack.accept(0);
    return count[0];
}

public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n == 0) return 0;
    // Precompute adjacency matrix where sum is perfect square
    boolean[][] can = new boolean[n][n];
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (i == j) continue;
            int sum = A[i] + A[j];
            int sqrt = (int) Math.sqrt(sum);
            can[i][j] = sqrt * sqrt == sum;
        }
    }
    int fullMask = (1 << n) - 1;
    long[][] dp = new long[1 << n][n];
    // Initialize: each element alone is a valid permutation
    for (int i = 0; i < n; i++) {
        dp[1 << i][i] = 1;
    }
    // Build up DP
    for (int mask = 1; mask <= fullMask; mask++) {
        for (int last = 0; last < n; last++) {
            if ((mask & (1 << last)) == 0 || dp[mask][last] == 0) continue;
            for (int next = 0; next < n; next++) {
                if ((mask & (1 << next)) != 0) continue;
                if (can[last][next]) {
                    dp[mask | (1 << next)][next] += dp[mask][last];
                }
            }
        }
    }
    long result = 0;
    for (int i = 0; i < n; i++) {
        result += dp[fullMask][i];
    }
    return (int) result;
}

public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n == 0) return 1;
    boolean[][] square = new boolean[n][n];
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            int sum = A[i] + A[j];
            int sqrt = (int) Math.sqrt(sum);
            square[i][j] = sqrt * sqrt == sum;
        }
    }
    int[] count = new int[1];
    boolean[] used = new boolean[n];
    class Backtrack {
        void dfs(int pos, int prev) {
            if (pos == n) {
                count[0]++;
                return;
            }
            for (int i = 0; i < n; i++) {
                if (!used[i] && (pos == 0 || square[prev][i])) {
                    used[i] = true;
                    dfs(pos + 1, i);
                    used[i] = false;
                }
            }
        }
    }
    Backtrack bt = new Backtrack();
    for (int i = 0; i < n; i++) {
        used[i] = true;
        bt.dfs(1, i);
        used[i] = false;
    }
    return count[0];
}

public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) {
        return 0;
    }
    int n = heights.length;
    // Stack to hold indices of bars, maximum size n+1 to handle dummy at end
    int[] stack = new int[n + 1];
    int top = -1;
    int maxArea = 0;
    for (int i = 0; i <= n; i++) {
        // Use 0 as sentinel height after the last bar
        int curHeight = (i == n) ? 0 : heights[i];
        while (top >= 0 && curHeight < heights[stack[top]]) {
            int height = heights[stack[top--]];
            int width = (top == -1) ? i : i - stack[top] - 1;
            int area = height * width;
            if (area > maxArea) {
                maxArea = area;
            }
        }
        stack[++top] = i;
    }
    return maxArea;
}

public static int largestRectangleArea(int[] heights) {
