public static int[] diagonalOrder(int[][] mat) {
    int m = mat.length;
    if (m == 0) return new int[0];
    int n = mat[0].length;
    int[] res = new int[m * n];
    int idx = 0;
    for (int d = 0; d <= m + n - 2; d++) {
        int rStart = Math.max(0, d - n + 1);
        int rEnd = Math.min(m - 1, d);
        if (d % 2 == 0) {
            for (int r = rEnd; r >= rStart; r--) {
                int c = d - r;
                res[idx++] = mat[r][c];
            }
        } else {
            for (int r = rStart; r <= rEnd; r++) {
                int c = d - r;
                res[idx++] = mat[r][c];
            }
        }
    }
    return res;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return new int[0];
    }
    int rows = mat.length;
    int cols = mat[0].length;
    int total = rows * cols;
    int[] result = new int[total];
    int index = 0;
    int maxSum = rows + cols - 2;

    for (int sum = 0; sum <= maxSum; sum++) {
        int startRow = Math.max(0, sum - (cols - 1));
        int endRow = Math.min(rows - 1, sum);

        if (sum % 2 == 0) {
            for (int r = endRow; r >= startRow; r--) {
                int c = sum - r;
                result[index++] = mat[r][c];
            }
        } else {
            for (int r = startRow; r <= endRow; r++) {
                int c = sum - r;
                result[index++] = mat[r][c];
            }
        }
    }

    return result;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return new int[0];
    }
    int m = mat.length;
    int n = mat[0].length;
    int[] result = new int[m * n];
    int index = 0;

    for (int sum = 0; sum < m + n - 1; sum++) {
        if (sum % 2 == 0) {
            int x = Math.min(sum, m - 1);
            int y = sum - x;
            while (x >= 0 && y < n) {
                result[index++] = mat[x][y];
                x--;
                y++;
            }
        } else {
            int y = Math.min(sum, n - 1);
            int x = sum - y;
            while (y >= 0 && x < m) {
                result[index++] = mat[x][y];
                x++;
                y--;
            }
        }
    }

    return result;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return new int[0];
    }
    int m = mat.length;
    int n = mat[0].length;
    int[] result = new int[m * n];
    int row = 0, col = 0;
    int direction = 1; // 1: up-right, -1: down-left

    for (int i = 0; i < result.length; i++) {
        result[i] = mat[row][col];

        if (direction == 1) {
            if (col == n - 1) {          // hit last column
                row++;
                direction = -1;
            } else if (row == 0) {       // hit first row
                col++;
                direction = -1;
            } else {
                row--;
                col++;
            }
        } else { // direction == -1
            if (row == m - 1) {          // hit last row
                col++;
                direction = 1;
            } else if (col == 0) {       // hit first column
                row++;
                direction = 1;
            } else {
                row++;
                col--;
            }
        }
    }
    return result;
}

public static int[] diagonalOrder(int[][] mat) {
