        return new int[0];
    }
    int m = mat.length;
    int n = mat[0].length;
    int[] res = new int[m * n];
    int index = 0;
    for (int d = 0; d <= m + n - 2; d++) {
        java.util.List<Integer> temp = new java.util.ArrayList<>();
        for (int i = 0; i < m; i++) {
            int j = d - i;
            if (j >= 0 && j < n) {
                temp.add(mat[i][j]);
            }
        }
        if (d % 2 == 0) {
            java.util.Collections.reverse(temp);
        }
        for (int val : temp) {
            res[index++] = val;
        }
    }
    return res;
}

public static int findSmallestInteger(int n) {
    char[] digits = String.valueOf(n).toCharArray();
    int i = digits.length - 2;
    while (i >= 0 && digits[i] >= digits[i + 1]) {
        i--;
    }
    if (i < 0) {
        return -1;
    }
    int j = digits.length - 1;
    while (j > i && digits[j] <= digits[i]) {
        j--;
    }
    char temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;
    int left = i + 1;
    int right = digits.length - 1;
    while (left < right) {
        char t = digits[left];
        digits[left] = digits[right];
        digits[right] = t;
        left++;
        right--;
    }
    String resultStr = new String(digits);
    long resultLong;
    try {
        resultLong = Long.parseLong(resultStr);
    } catch (NumberFormatException e) {
        return -1;
    }
    if (resultLong > Integer.MAX_VALUE) {
        return -1;
    }
    return (int) resultLong;
}

