public static int findSmallestInteger(int n) {
    // Convert integer to an array of its digit characters
    char[] digits = Integer.toString(n).toCharArray();
    int len = digits.length;

    // Step 1: Find the longest non-increasing suffix
    int i = len - 2;
    while (i >= 0 && digits[i] >= digits[i + 1]) {
        i--;
    }

    // If the entire sequence is non-increasing, no larger permutation exists
    if (i < 0) {
        return -1;
    }

    // Step 2: Find the rightmost successor to pivot in the suffix
    int j = len - 1;
    while (digits[j] <= digits[i]) {
        j--;
    }

    // Swap pivot with successor
    char temp = digits[i];
    digits[i] = digits[j];
    digits[j] = temp;

    // Step 3: Reverse the suffix starting at i+1
    int left = i + 1;
    int right = len - 1;
    while (left < right) {
        temp = digits[left];
        digits[left] = digits[right];
        digits[right] = temp;
        left++;
        right--;
    }

    // Build the resulting integer, checking for overflow
    long result = 0;
    for (char d : digits) {
        result = result * 10 + (d - '0');
        if (result > Integer.MAX_VALUE) {
            return -1; // exceeds int range
        }
    }

    return (int) result;
}

