public static java.util.List<String> centerSymmetricNumbers(int n) {
    java.util.List<String> res = new java.util.ArrayList<>();
    if (n <= 0) {
        return res;
    }
    class Builder {
        void backtrack(char[] curr, int left, int right) {
            if (left > right) {
                if (n > 1 && curr[0] == '0') {
                    return;
                }
                res.add(new String(curr));
                return;
            }
            if (left == right) {
                char[] mids = {'0', '1', '8'};
                for (char c : mids) {
                    curr[left] = c;
                    backtrack(curr, left + 1, right - 1);
                }
            } else {
                char[][] pairs = {
                    {'0', '0'}, {'1', '1'}, {'6', '9'}, {'8', '8'}, {'9', '6'}
                };
                for (char[] pair : pairs) {
                    if (left == 0 && pair[0] == '0' && n > 1) {
                        continue; // leading zero not allowed for numbers with length > 1
                    }
                    curr[left] = pair[0];
                    curr[right] = pair[1];
                    backtrack(curr, left + 1, right - 1);
                }
            }
        }
    }
    Builder b = new Builder();
    char[] current = new char[n];
    b.backtrack(current, 0, n - 1);
    return res;
}

public static List<String> centerSymmetricNumbers(int n) {
    List<String> result = new ArrayList<>();
    if (n <= 0) return result;
    if (n == 1) {
        result.add("0");
        result.add("1");
        result.add("8");
        return result;
    }
    char[] current = new char[n];
    build(n, 0, n - 1, current, result);
    Collections.sort(result);
    return result;
}

