public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        return 0;
    }
    int[] dp = new int[n + 1];
    dp[0] = 0;
    // Initialize all values to a large number
    for (int i = 1; i <= n; i++) {
        dp[i] = Integer.MAX_VALUE;
        for (int j = 1; j * j <= i; j++) {
            int square = j * j;
            if (dp[i - square] != Integer.MAX_VALUE) {
                dp[i] = Math.min(dp[i], dp[i - square] + 1);
            }
        }
    }
    return dp[n];
}

public static int minPerfectSquareSum(int n) {
    if (n <= 0) return 0;
    int[] dp = new int[n + 1];
    dp[0] = 0;
    for (int i = 1; i <= n; i++) {
        dp[i] = Integer.MAX_VALUE;
        for (int j = 1; j * j <= i; j++) {
            int square = j * j;
            dp[i] = Math.min(dp[i], dp[i - square] + 1);
        }
    }
    return dp[n];
}

public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        return 0;
    }
    int[] dp = new int[n + 1];
    dp[0] = 0;
    for (int i = 1; i <= n; i++) {
        dp[i] = i; // worst case: i ones
        for (int j = 1; j * j <= i; j++) {
            int square = j * j;
            int candidate = dp[i - square] + 1;
            if (candidate < dp[i]) {
                dp[i] = candidate;
            }
        }
    }
    return dp[n];
}

public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        return 0;
    }
    int[] dp = new int[n + 1];
    // Initialize dp[i] to a large number
    for (int i = 1; i <= n; i++) {
        dp[i] = Integer.MAX_VALUE;
    }
    dp[0] = 0;
    // Precompute list of squares up to n
    int maxRoot = (int) Math.sqrt(n);
    int[] squares = new int[maxRoot];
    for (int i = 0; i < maxRoot; i++) {
        squares[i] = (i + 1) * (i + 1);
    }
    // Dynamic programming to compute minimal count
    for (int i = 1; i <= n; i++) {
        for (int square : squares) {
            if (square > i) {
                break;
            }
            int candidate = dp[i - square] + 1;
            if (candidate < dp[i]) {
                dp[i] = candidate;
            }
        }
    }
    return dp[n];
}

public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        return 0;
    }
    int[] dp = new int[n + 1];
    dp[0] = 0;
    for (int i = 1; i <= n; i++) {
        int min = Integer.MAX_VALUE;
        for (int j = 1; j * j <= i; j++) {
            int square = j * j;
            int candidate = dp[i - square] + 1;
            if (candidate < min) {
                min = candidate;
            }
        }
        dp[i] = min;
    }
    return dp[n];
}

public static String reverseWords(String s) {
    if (s == null || s.isEmpty()) {
        return s;
    }
    StringBuilder result = new StringBuilder();
    int i = 0;
    int n = s.length();
    while (i < n) {
        if (Character.isWhitespace(s.charAt(i))) {
            // Preserve whitespace exactly
            result.append(s.charAt(i));
            i++;
        } else {
            // Find the end of the current word
            int start = i;
            while (i < n && !Character.isWhitespace(s.charAt(i))) {
                i++;
            }
            // Reverse the word from start to i-1
            for (int j = i - 1; j >= start; j--) {
                result.append(s.charAt(j));
            }
        }
    }
    return result.toString();
}

public static String reverseWords(String s) {
    if (s == null) {
        return null;
    }
    String[] words = s.split(" ");
    StringBuilder result = new StringBuilder();
    for (int i = 0; i < words.length; i++) {
        String word = words[i];
        for (int j = word.length() - 1; j >= 0; j--) {
            result.append(word.charAt(j));
        }
        if (i < words.length - 1) {
            result.append(" ");
        }
    }
    return result.toString();
}

public static String reverseWords(String s) {
    if (s == null) {
        return null;
    }
    StringBuilder result = new StringBuilder();
    StringBuilder word = new StringBuilder();

    for (int i = 0; i < s.length(); i++) {
        char c = s.charAt(i);
        if (c == ' ') {
            // Append the reversed current word
            result.append(word.reverse());
            word.setLength(0); // clear the word buffer
            result.append(' ');
        } else {
            word.append(c);
        }
    }
    // Append the last word (reverse it if necessary)
    result.append(word.reverse());

    return result.toString();
}

public static String reverseWords(String s) {
    if (s == null) {
        return null;
    }
    StringBuilder result = new StringBuilder();
    StringBuilder currentWord = new StringBuilder();
    for (int i = 0; i < s.length(); i++) {
        char ch = s.charAt(i);
        if (ch != ' ') {
            currentWord.append(ch);
        } else {
            // Append the reversed current word to result
            for (int j = currentWord.length() - 1; j >= 0; j--) {
                result.append(currentWord.charAt(j));
            }
            currentWord.setLength(0); // reset for next word
            result.append(ch); // preserve the space
        }
    }
    // Append the last word if any
    for (int j = currentWord.length() - 1; j >= 0; j--) {
        result.append(currentWord.charAt(j));
    }
    return result.toString();
}

public static String reverseWords(String s) {
    if (s == null || s.isEmpty()) {
        return s;
    }
    StringBuilder result = new StringBuilder();
    int i = 0;
    int n = s.length();
    while (i < n) {
        // Find the start of the next word
        int wordStart = i;
        while (i < n && s.charAt(i) != ' ') {
            i++;
        }
        // Reverse the word from wordStart to i-1
        for (int j = i - 1; j >= wordStart; j--) {
            result.append(s.charAt(j));
        }
        // Append any following spaces
        while (i < n && s.charAt(i) == ' ') {
            result.append(' ');
            i++;
        }
    }
    return result.toString();
}
